INSERT INTO restaurants (id, sort_order, path, name, short_label, logo_image, header_icon, tone, badge, hero_heading, hero_text, about_heading, rating_value, yandex_reviews_url, phone, phone_href, telegram, legal_info, is_placeholder) VALUES ('ekranidze', 0, '/ekranidze', 'Экранидзе', 'Экранидзе', '/logos/ekranidze-emblem.png', '/logos/ekranidze-emblem-round.png', 'clay', 'Люберцы, грузинская кухня', 'Хинкали и хачапури по традиционным рецептам', 'Уютный грузинский ресторан с летней верандой — приходите поужинать или заберите блюда с собой. Расскажем ниже про меню и доставку.', 'Уголок Грузии в Люберцах', '4.8', 'https://yandex.ru/maps/org/169306513048', '+7 901 513-71-96', 'tel:+79015137196', 'https://telegram.me/ekranidze', 'ИНН 5027322822 · ОГРН 1235000143784', 0);
INSERT INTO restaurant_about_paragraphs (restaurant_id, sort_order, body) VALUES ('ekranidze', 0, 'Готовим по традиционным грузинским рецептам — от хачапури по-аджарски до наваристого харчо. Стараемся брать свежие сезонные продукты и держать в меню и классику, и домашние блюда, которые не встретишь в обычном ресторане.');
INSERT INTO restaurant_about_paragraphs (restaurant_id, sort_order, body) VALUES ('ekranidze', 1, 'Внутри — тёплая, семейная атмосфера: сюда приходят и на ужин с детьми, и посидеть с друзьями на веранде летним вечером.');
